// Evaluate the defining recursion on records with several lanes per coordinate
static void packed_direct(FastCDFFPacked16* restrict out, const FastCDFFPacked16* x,
        const FastCDFFPacked16* y, size_t n, FastCDFFPacked16* restrict work,
        size_t points, const Context* ctx) {
    // With a whole vector per coordinate, run the value schedule
    if (points == 32) {
        FASTCD_FF_NAME(direct_values)
        ((Word*)out, (const Word*)x, (const Word*)y, n, (Word*)work, ctx);
        return;
    }
    // Records that fill one vector are leaves
    if (n == 32 / points) {
        switch (points) {
            case 1:
                direct_leaf1(out, x, y, ctx);
                return;
            case 2:
                direct_leaf2(out, x, y, ctx);
                return;
            case 4:
                direct_leaf4(out, x, y, ctx);
                return;
            case 8:
                direct_leaf8(out, x, y, ctx);
                return;
            case 16:
                direct_leaf16(out, x, y, ctx);
                return;
            default:
                __builtin_trap();
        }
    }
    // One conjugated half, one partial product, then the children's scratch
    size_t h = n / 2, size = h * points;
    FastCDFFPacked16* temp = work;
    FastCDFFPacked16* product = temp + size;
    FastCDFFPacked16* child = product + size;
    // Lower half: ac - conjugate(d)b, keeping the scalar coordinate of d
    packed_direct(out, x, y, h, child, points, ctx);
    for (size_t i = 0; i < size; i += 32) {
        Word value = direct_load(y + size + i);
        direct_store(temp + i, VSUB(VZERO, value));
    }
    memcpy(temp, y + size, points * sizeof(*temp));
    packed_direct(product, temp, x + size, h, child, points, ctx);
    for (size_t i = 0; i < size; i += 32) {
        Word a = direct_load(out + i), b = direct_load(product + i);
        direct_store(out + i, VSUB(a, b));
    }
    // Upper half: da + b conjugate(c), keeping the scalar coordinate of c
    packed_direct(out + size, y + size, x, h, child, points, ctx);
    for (size_t i = 0; i < size; i += 32) {
        Word value = direct_load(y + i);
        direct_store(temp + i, VSUB(VZERO, value));
    }
    memcpy(temp, y, points * sizeof(*temp));
    packed_direct(product, x + size, temp, h, child, points, ctx);
    for (size_t i = 0; i < size; i += 32) {
        Word a = direct_load(out + size + i), b = direct_load(product + i);
        direct_store(out + size + i, VADD(a, b));
    }
}
